args<-commandArgs(trailingOnly=TRUE);if(length(args)!=5)stop("usage: seed n regime out src");script<-sub("^--file=","",commandArgs(FALSE)[grep("^--file=",commandArgs(FALSE))][1]);base<-dirname(normalizePath(script));seed<-as.integer(args[1]);n<-as.integer(args[2]);regime<-args[3];out<-args[4];src<-args[5];source(file.path(base,"R/core.R"));f<-d102_fixture(seed,n,regime);rec<-list(seed=seed,n=n,regime=regime,attempts=list());for(m in names(d102_methods))for(s in names(d102_starts(f$y,f$L,f$beta))){key<-paste(m,s,sep="-");rec$attempts[[key]]<-tryCatch(d102_fit(f,m,d102_starts(f$y,f$L,f$beta)[[s]],src),error=function(e)list(status="failed",reason=conditionMessage(e)))};tmp<-paste0(out,".tmp");saveRDS(rec,tmp);if(!file.rename(tmp,out))stop("exclusive publish failed")
